import {verbById,verbChange} from './verbs.js';
const token=(jp,role,note)=>({jp,role,note});
const topic=(jp,meaning)=>token(jp,'topic',`${meaning}，是這句話談論的對象。`);
const wa=()=>token('は','particle','把前面的對象提出來當話題。這個助詞寫作「は」，讀作「わ」。');
const noun=(jp,meaning)=>token(jp,'noun',`${meaning}。這個名詞說明身分或類別。`);
const ending=(jp='です')=>token(jp,'ending',jp==='です'?'接在名詞後面，以禮貌語氣完成這個說明。':`「${jp}」把名詞句改成否定，意思是「不是」。`);
const ka=()=>token('か','question','放在禮貌句句尾，表示正在提問。本課先練「ですか」的問法。');
const object=(jp,meaning)=>token(jp,'object',`${meaning}，是這個動作作用的對象。`);
const wo=()=>token('を','particle','標示動作對象，讀作「お」。前面的名詞是被喝、被讀或被看的東西。');
const place=jp=>token(jp,'place','動作發生的場所，後面用「で」連接。');
const de=()=>token('で','particle','表示在前面這個場所進行後面的動作。');
const time=(jp,note)=>token(jp,'time',note);
const verb=(jp,full,meaning)=>token(jp,'verb',`這是「${full}」去掉「ます」後的部分，表示「${meaning}」的動作。後面接本題要練習的禮貌句尾。`);
const verbEnding=jp=>token(jp,'ending',({'ます':'禮貌的非過去肯定句尾。依時間情境可說明現在的習慣或未來的行動。','ません':'禮貌的非過去否定句尾，依情境表示平常不做或接下來不做。','ました':'禮貌的過去肯定句尾，表示已經發生的動作。','ませんでした':'禮貌的過去否定句尾，表示過去沒有做某件事。'})[jp]);
const adjective=(jp,note)=>token(jp,'adjective',note);
const adjectiveEnding=()=>token('です','ending','接在這個形容詞的敘述形式後，讓說明帶有禮貌語氣。這裡不必翻成「是」。');
const actionHint='先把「場所＋で」與「對象＋を」各自連好，再接動詞的部分和本題要求的句尾。留意肯定、否定，以及動作發生的時間。';
const adjectiveHint='先用「話題＋は」提出對象，再接形容詞與禮貌句尾「です」。本題是在敘述狀態，不是用形容詞直接修飾後面的名詞。';
export const exampleSentence=e=>e.parts.map(p=>p.jp).join('')+'。';
const example=(scene,parts,zh)=>({scene,parts,zh});
const negEndings=['じゃありません','ではありません','じゃないです','ではないです'];
