const choice=(id,use,context,options,answers,why,wrong)=>({id,type:'choice',use,context,options,answers,why,wrong});
const build=(id,use,context,parts,translation,why,hint='先找出話題，再接「は」，接著說明身分或類別，最後放句尾；提問時再加「か」。請對照完整答案，看看詞塊之間的關係。',otherOrders=[])=>({id,type:'build',use,context,parts,orders:[parts.map((_,i)=>i),...otherOrders],translation,why,hint});
const transform=(id,use,context,source,prefix,options,answers,translation,why,wrong)=>({id,type:'transform',use,context,source,prefix,options,answers,translation,why,wrong});
const conjugate=(id,use,verbId,target,context,wrongOptions,wrong,groupUse='groups-basic')=>{
  const v=verbById(verbId);return {id,type:'conjugate',use,verbId,target,groupUse,context,source:v.jp,sourceLabel:'辭書形 · 原本的動詞',prefix:target==='te'?'':v.phrase,formOnly:target==='te',options:[v[target],...wrongOptions],answers:[v[target]],translation:target==='te'?'這裡完成的是て形；接上後面的表現，才會形成這次要說的意思。':(target==='masu'?v.positive:v.negative)+'。',why:verbChange(v,target).note,wrong};
};
const dictionaryTransform=(...args)=>({...transform(...args),sourceLabel:'辭書形 · 原本的動詞'});
